// Keep the CLI/server prompt independent of React UI's browser component imports.
import { openuiLibrary, openuiPromptOptions } from '@openuidev/react-ui/genui-lib';
import { writeFileSync } from 'node:fs';
const { schema: _schema, ...spec } = openuiLibrary.toSpec();
writeFileSync(new URL('../src/server/shared/chatFullUICatalog.ts', import.meta.url),
  '// Generated by scripts/generate-chat-ui-catalog.mjs; regenerate after updating the UI dependency.\n' +
  'import type { LibrarySpec, SystemPromptOptions } from "@openuidev/lang-core";\n' +
  `export const chatFullUISpec: LibrarySpec = ${JSON.stringify(spec, null, 2)};\n` +
  `export const chatFullUIOptions: SystemPromptOptions = ${JSON.stringify(openuiPromptOptions, null, 2)};\n`);
console.log(`Generated ${Object.keys(spec.components).length} component signatures.`);
